// Security: Validate HMAC Signature and Timestamp Replay Protection
const crypto = require('crypto');

const headers = $input.item.json.headers || {};
const rawBody = $input.item.json.body || {};
const signatureHeader = headers['x-lendloop-signature'] || '';
const timestampHeader = headers['x-lendloop-timestamp'] || '';
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('Unauthorized: Server webhook secret is not configured.');
}

// 1. Replay attack verification (5 min tolerance)
const now = Date.now();
const reqTime = parseInt(timestampHeader, 10);
if (isNaN(reqTime) || Math.abs(now - reqTime) > 300000) {
  throw new Error('Unauthorized: Webhook timestamp expired or invalid (replay protection).');
}

// 2. Compute expected HMAC-SHA256
const bodyString = JSON.stringify(rawBody);
const expectedSignature = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(`${timestampHeader}.${bodyString}`)
  .digest('hex');

// Constant time comparison
const sigBuffer = Buffer.from(signatureHeader);
const expectedBuffer = Buffer.from(expectedSignature);
const isValid = sigBuffer.length === expectedBuffer.length && crypto.timingSafeEqual(sigBuffer, expectedBuffer);

if (!isValid) {
  throw new Error('Unauthorized: Invalid HMAC signature.');
}

const event = rawBody.event;
const data = rawBody.data || {};

return [{
  json: {
    isValid: true,
    event: event,
    data: data,
    receivedAt: now
  }
}];

const item = $json.data;
return [{
  json: {
    channel: 'email',
    recipient: item.ownerEmail,
    subject: `[LendLoop] New Borrow Request for "${item.toolName}"`,
    bodyText: `Hello ${item.ownerName},\n\n${item.borrowerName} has requested to borrow your "${item.toolName}" from ${item.startDate} to ${item.endDate}.\n\nNotes: ${item.notes || 'None'}\n\nPlease visit LendLoop to review and approve this request.`,
    event: 'REQUEST_CREATED',
    timestamp: Date.now()
  }
}];

const item = $json.data;
return [{
  json: {
    channel: 'email',
    recipient: item.borrowerEmail,
    subject: `[LendLoop] Your Borrow Request for "${item.toolName}" was Approved!`,
    bodyText: `Great news ${item.borrowerName}!\n\n${item.ownerName} approved your request for "${item.toolName}" (${item.startDate} to ${item.endDate}).\n\nPlease coordinate pickup and remember to take good care of the tool!`,
    event: 'REQUEST_APPROVED',
    timestamp: Date.now()
  }
}];

const item = $json.data;
return [{
  json: {
    channel: 'email',
    recipient: item.borrowerEmail,
    subject: `[LendLoop] Update on your request for "${item.toolName}"`,
    bodyText: `Hello ${item.borrowerName},\n\nUnfortunately ${item.ownerName} was unable to approve your request for "${item.toolName}" at this time.\n\nCheck out other available tools on LendLoop!`,
    event: 'REQUEST_REJECTED',
    timestamp: Date.now()
  }
}];

const item = $json.data;
return [{
  json: {
    channel: 'email',
    recipient: item.borrowerEmail,
    subject: `[LendLoop] Return Confirmed for "${item.toolName}"`,
    bodyText: `Hello ${item.borrowerName},\n\n${item.ownerName} has marked "${item.toolName}" as returned. Thank you for participating in our neighborhood lending loop!`,
    event: 'REQUEST_RETURNED',
    timestamp: Date.now()
  }
}];

// Dispatches notification (via Email / Webhook / Structured Console Audit)
const payload = $json;
console.log(`[n8n Notification Dispatched] To: ${payload.recipient} | Subject: ${payload.subject}`);

return [{
  json: {
    status: 'SENT',
    recipient: payload.recipient,
    subject: payload.subject,
    sentAt: Date.now()
  }
}];
